// Reads a form submission. The transcript can be pasted, uploaded as a file, or both.
const form = $('Proposal Request Form').first().json;
const input = $input.first().json;
const clean = (value) => (value === undefined || value === null ? '' : String(value)).trim();

// Caption files (.vtt, .srt) have cue numbers and timestamps on every few lines.
// Keep only the spoken text, with speaker names from WebVTT voice tags.
function captionsToText(text) {
  if (!/-->/.test(text)) return text;
  const lines = [];
  for (let line of text.replace(/\r/g, '').split('\n')) {
    line = line.trim();
    if (!line || /^WEBVTT/i.test(line) || /^(NOTE|STYLE|REGION)\b/.test(line)) continue;
    if (/^\d+$/.test(line) || /-->/.test(line)) continue;
    line = line
      .replace(/<v(?:\.[^\s>]+)?\s+([^>]+)>/g, '$1: ')
      .replace(/<\/?[^>]+>/g, '')
      .replace(/\s+/g, ' ')
      .trim();
    if (line && lines[lines.length - 1] !== line) lines.push(line);
  }
  return lines.join('\n');
}

let fileText = '';
if ($('Read PDF Transcript').isExecuted) fileText = clean(input.text);
else if ($('Read Text Transcript').isExecuted) fileText = clean(captionsToText(clean(input.file_text)));

const fileName = clean(form.transcript_file?.filename);
const pasted = clean(form.transcript);
const sources = [];
if (pasted) sources.push('pasted text');
if (fileName) sources.push(`file: ${fileName}`);

return [{
  json: {
    source: 'form',
    client_name: clean(form.client_name),
    client_company: clean(form.client_company),
    client_email: clean(form.client_email).toLowerCase(),
    rep_name: clean(form.rep_name),
    rep_email: clean(form.rep_email).toLowerCase(),
    notes: clean(form.notes),
    transcript: [pasted, fileText].filter(Boolean).join('\n\n'),
    transcript_source: sources.join(' + '),
    file_name: fileName,
    file_has_text: fileName ? fileText.length > 0 : null,
  },
}];

// Reads a POST request to the Proposal API. The body is JSON with the same fields as the form.
let body = $input.first().json.body ?? {};
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (error) {
    body = {};
  }
}
const clean = (value) => (value === undefined || value === null ? '' : String(value)).trim();

return [{
  json: {
    source: 'api',
    client_name: clean(body.client_name),
    client_company: clean(body.client_company),
    client_email: clean(body.client_email).toLowerCase(),
    rep_name: clean(body.rep_name),
    rep_email: clean(body.rep_email).toLowerCase(),
    notes: clean(body.notes),
    transcript: clean(body.transcript),
    transcript_source: 'api',
    file_name: '',
    file_has_text: null,
  },
}];

// Checks the request and the Settings, reads the pricing catalog, and builds the AI prompt.
const MAX_TRANSCRIPT_CHARS = 150000;
const MIN_TRANSCRIPT_CHARS = 100;

const r = $input.first().json;
const clean = (value) => (value === undefined || value === null ? '' : String(value)).trim();
const idFrom = (value, pattern) => {
  const text = clean(value);
  const match = text.match(pattern);
  return match ? match[1] : text;
};
const isEmail = (value) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
const escapeHtml = (text) => String(text)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const errors = [];
const warnings = [];

// Settings
const settings = {
  templateDocId: idFrom(r.templateDocId, /\/d\/([\w-]{20,})/),
  driveFolderId: idFrom(r.driveFolderId, /folders\/([\w-]{10,})/),
  companyName: clean(r.companyName) || 'Our company',
  currency: clean(r.currency).toUpperCase() || 'USD',
  locale: clean(r.locale) || 'en-US',
  validityDays: Number(r.proposalValidityDays) > 0 ? Number(r.proposalValidityDays) : 30,
  linkSharingRole: clean(r.linkSharingRole).toLowerCase(),
};
if (!settings.templateDocId) {
  errors.push('Settings: add the ID of your proposal template Google Doc to templateDocId.');
}
if (settings.linkSharingRole && !['reader', 'commenter'].includes(settings.linkSharingRole)) {
  errors.push('Settings: linkSharingRole must be empty, "reader", or "commenter".');
}
try {
  new Intl.NumberFormat(settings.locale, { style: 'currency', currency: settings.currency });
} catch (error) {
  errors.push(`Settings: currency "${settings.currency}" with locale "${settings.locale}" is not valid. Use a code like USD and a locale like en-US.`);
}

// Pricing catalog
let catalog = [];
try {
  const parsed = typeof r.pricingCatalog === 'string' ? JSON.parse(r.pricingCatalog) : r.pricingCatalog;
  if (!Array.isArray(parsed)) throw new Error('it must be a JSON list of services');
  const seen = new Set();
  parsed.forEach((service, index) => {
    const id = clean(service?.id);
    const name = clean(service?.name);
    const unitPrice = Number(service?.unit_price);
    if (!id || !name || !Number.isFinite(unitPrice) || unitPrice < 0) {
      errors.push(`Settings: pricingCatalog item ${index + 1} needs an id, a name, and a unit_price of 0 or more.`);
      return;
    }
    if (seen.has(id.toLowerCase())) {
      errors.push(`Settings: pricingCatalog has the id "${id}" more than once.`);
      return;
    }
    seen.add(id.toLowerCase());
    catalog.push({
      id,
      name,
      description: clean(service.description),
      unit_price: unitPrice,
      unit: clean(service.unit) || 'unit',
    });
  });
} catch (error) {
  errors.push(`Settings: pricingCatalog is not valid JSON (${error.message}).`);
}
if (!errors.some((e) => e.includes('pricingCatalog')) && catalog.length === 0) {
  errors.push('Settings: pricingCatalog has no services.');
}

// Request
const request = {
  client_name: clean(r.client_name),
  client_company: clean(r.client_company),
  client_email: clean(r.client_email),
  rep_name: clean(r.rep_name),
  rep_email: clean(r.rep_email),
  notes: clean(r.notes),
};
const required = [
  ['client_name', 'the client contact name'],
  ['client_company', 'the client company'],
  ['client_email', 'the client email'],
  ['rep_name', 'the sales rep name'],
  ['rep_email', 'the sales rep email'],
];
for (const [field, label] of required) {
  if (!request[field]) errors.push(`Add ${label} (${field}).`);
}
for (const field of ['client_email', 'rep_email']) {
  if (request[field] && !isEmail(request[field])) errors.push(`${field} "${request[field]}" is not a valid email address.`);
}

let transcript = clean(r.transcript);
if (r.file_name && r.file_has_text === false) {
  errors.push(`The file "${r.file_name}" has no readable text. Scanned PDFs need OCR first, or paste the transcript instead.`);
} else if (transcript.length < MIN_TRANSCRIPT_CHARS) {
  errors.push(`Add the call transcript (paste it, or upload a .txt, .vtt, .srt, or .pdf file). It needs at least ${MIN_TRANSCRIPT_CHARS} characters.`);
}
if (transcript.length > MAX_TRANSCRIPT_CHARS) {
  transcript = transcript.slice(0, MAX_TRANSCRIPT_CHARS);
  warnings.push(`The transcript was longer than ${MAX_TRANSCRIPT_CHARS.toLocaleString('en-US')} characters, so only the first ${MAX_TRANSCRIPT_CHARS.toLocaleString('en-US')} were used.`);
}

if (errors.length) {
  return [{
    json: {
      ok: false,
      source: r.source,
      statusCode: 400,
      title: "The proposal wasn't created",
      message: `<p>Fix the following, then submit the form again:</p><ul>${errors.map((e) => `<li>${escapeHtml(e)}</li>`).join('')}</ul>`,
      body: { ok: false, errors },
    },
  }];
}

const money = new Intl.NumberFormat(settings.locale, { style: 'currency', currency: settings.currency });
const catalogText = catalog
  .map((s) => `- id: ${s.id} | ${s.name} | ${money.format(s.unit_price)} per ${s.unit}${s.description ? ` | ${s.description}` : ''}`)
  .join('\n');

const prompt = [
  'Write a sales proposal and a follow-up email from this sales call.',
  '',
  `Seller (our company): ${settings.companyName}`,
  `Sales rep: ${request.rep_name} <${request.rep_email}>`,
  `Client contact: ${request.client_name} <${request.client_email}>`,
  `Client company: ${request.client_company}`,
  `Proposal date: ${$now.toFormat('yyyy-MM-dd')}`,
  '',
  "Rep's notes (these take priority over the transcript):",
  request.notes || 'None',
  '',
  'Pricing catalog. Choose pricing_lines only from these ids:',
  catalogText,
  '',
  'Call transcript:',
  '"""',
  transcript,
  '"""',
].join('\n');

return [{
  json: {
    ok: true,
    source: r.source,
    ...request,
    transcript_source: r.transcript_source,
    transcript_chars: transcript.length,
    settings,
    catalog,
    warnings,
    prompt,
  },
}];

