// Prices the AI's chosen catalog items and builds the text for every template placeholder.
// The AI only picks catalog ids and quantities. Prices and totals come from the catalog here.
const req = $('Check Request').first().json;
const ai = $input.first().json.output ?? $input.first().json;
const { settings, catalog } = req;
const clean = (value) => (value === undefined || value === null ? '' : String(value)).trim();
const list = (value) => (Array.isArray(value) ? value.map(clean).filter(Boolean) : []);
const money = new Intl.NumberFormat(settings.locale, { style: 'currency', currency: settings.currency });
const round2 = (n) => Math.round(n * 100) / 100;
const warnings = [...(req.warnings || [])];

// Pricing
const byId = new Map(catalog.map((service) => [service.id.toLowerCase(), service]));
const lines = [];
const dropped = [];
for (const line of Array.isArray(ai.pricing_lines) ? ai.pricing_lines : []) {
  const id = clean(line?.catalog_id);
  const service = byId.get(id.toLowerCase());
  if (!service) {
    dropped.push(id || '(no id)');
    continue;
  }
  let quantity = Number(line.quantity);
  if (!Number.isFinite(quantity) || quantity <= 0) {
    quantity = 1;
    warnings.push(`The AI gave no valid quantity for "${service.name}", so 1 was used. Check it in the doc.`);
  }
  quantity = round2(quantity);
  lines.push({
    catalog_id: service.id,
    name: service.name,
    description: service.description,
    quantity,
    unit: service.unit,
    unit_price: service.unit_price,
    line_total: round2(service.unit_price * quantity),
    note: clean(line.note),
  });
}
if (dropped.length) {
  warnings.push(`Not in the pricing catalog, so left out of the price: ${dropped.join(', ')}.`);
}
if (!lines.length) {
  warnings.push('No catalog items were chosen, so the proposal has no pricing. Add it in the doc before you send it.');
}
const total = round2(lines.reduce((sum, line) => sum + line.line_total, 0));

const pricingText = lines.length
  ? lines.map((l) => `${l.name}: ${l.quantity} x ${money.format(l.unit_price)} per ${l.unit} = ${money.format(l.line_total)}${l.note ? ` (${l.note})` : ''}`).join('\n')
  : 'Pricing to be confirmed.';

const timelineText = (Array.isArray(ai.timeline) ? ai.timeline : [])
  .map((phase) => {
    const name = clean(phase?.phase);
    const duration = clean(phase?.duration);
    const description = clean(phase?.description);
    if (!name) return '';
    return `${name}${duration ? ` (${duration})` : ''}${description ? `: ${description}` : ''}`;
  })
  .filter(Boolean)
  .join('\n');

// Dates in the workflow's time zone, written for the Settings locale
const dateFormat = { year: 'numeric', month: 'long', day: 'numeric' };
const proposalDate = $now.setLocale(settings.locale).toLocaleString(dateFormat);
const validUntil = $now.plus({ days: settings.validityDays }).setLocale(settings.locale).toLocaleString(dateFormat);

// One entry per {{placeholder}} in the template. The order matches the Fill Proposal Placeholders node.
const placeholders = {
  proposal_title: clean(ai.proposal_title) || `Proposal for ${req.client_company}`,
  proposal_date: proposalDate,
  valid_until: validUntil,
  client_name: req.client_name,
  client_company: req.client_company,
  client_email: req.client_email,
  rep_name: req.rep_name,
  rep_email: req.rep_email,
  company_name: settings.companyName,
  executive_summary: clean(ai.executive_summary),
  client_goals: list(ai.client_goals).join('\n'),
  current_challenges: list(ai.current_challenges).join('\n'),
  proposed_solution: clean(ai.proposed_solution),
  scope_items: list(ai.scope_items).join('\n'),
  deliverables: list(ai.deliverables).join('\n'),
  timeline: timelineText,
  pricing_lines: pricingText,
  total_price: money.format(total),
  assumptions: list(ai.assumptions).join('\n'),
  next_steps: list(ai.next_steps).join('\n'),
};

return [{
  json: {
    source: req.source,
    client_name: req.client_name,
    client_company: req.client_company,
    client_email: req.client_email,
    rep_name: req.rep_name,
    rep_email: req.rep_email,
    template_doc_id: settings.templateDocId,
    folder_id: settings.driveFolderId || 'root',
    doc_name: `Proposal - ${req.client_company} - ${$now.toFormat('yyyy-MM-dd')}`,
    link_sharing_role: settings.linkSharingRole,
    email_subject: clean(ai.email_subject) || `Your proposal from ${settings.companyName}`,
    email_body: clean(ai.email_body) || `Hi ${req.client_name.split(' ')[0]},\n\nThank you for your time on our call. The proposal we discussed is ready for you to review.`,
    email_signature: `${req.rep_name}\n${settings.companyName}`,
    pricing: {
      currency: settings.currency,
      lines,
      total,
      total_formatted: money.format(total),
    },
    dropped_items: dropped,
    placeholders,
    placeholder_keys: Object.keys(placeholders),
    warnings,
  },
}];

