// Builds the success response: the form completion page and the API JSON.
const p = $('Price the Proposal').first().json;
const copy = $('Copy Proposal Template').first().json;
const fill = $('Fill Proposal Placeholders').first().json;
const draft = $input.first().json;
const escapeHtml = (text) => String(text)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const docUrl = `https://docs.google.com/document/d/${copy.id}/edit`;
const warnings = [...p.warnings];

// Docs returns one reply per replace request, in the same order as the placeholders.
const replies = Array.isArray(fill.replies) ? fill.replies : [];
const missing = p.placeholder_keys.filter((key, i) => !(replies[i]?.replaceAllText?.occurrencesChanged > 0));
if (missing.length) {
  warnings.push(`Not found in your template, so not filled in: ${missing.map((k) => `{{${k}}}`).join(', ')}.`);
}

let linkShared = false;
if (p.link_sharing_role) {
  const share = $('Share Doc Link').isExecuted ? $('Share Doc Link').first().json : {};
  if (share.error) {
    warnings.push(`Link sharing failed, so the doc is still private: ${share.error.message ?? share.error}`);
  } else {
    linkShared = true;
  }
}
const shareText = linkShared
  ? `Anyone with the link can ${p.link_sharing_role === 'commenter' ? 'comment on' : 'view'} the doc.`
  : 'The doc is private to your Google account. Share it with the client before you send the email.';

const message = [
  `<p>The proposal for <strong>${escapeHtml(p.client_company)}</strong> is ready, with a total of <strong>${escapeHtml(p.pricing.total_formatted)}</strong>.</p>`,
  `<p><a href="${docUrl}" target="_blank" rel="noopener">Open the proposal in Google Docs</a></p>`,
  `<p>A Gmail draft to ${escapeHtml(p.client_email)} is waiting in Drafts. Review the doc and the email, then send it.</p>`,
  `<p>${escapeHtml(shareText)}</p>`,
  warnings.length ? `<p>Check these before you send:</p><ul>${warnings.map((w) => `<li>${escapeHtml(w)}</li>`).join('')}</ul>` : '',
].join('');

return [{
  json: {
    ok: true,
    source: p.source,
    statusCode: 200,
    title: 'Your proposal is ready',
    message,
    body: {
      ok: true,
      client_company: p.client_company,
      doc_id: copy.id,
      doc_url: docUrl,
      doc_name: p.doc_name,
      gmail_draft_id: draft.id ?? null,
      gmail_message_id: draft.message?.id ?? null,
      link_shared: linkShared,
      total: p.pricing.total,
      total_formatted: p.pricing.total_formatted,
      currency: p.pricing.currency,
      pricing_lines: p.pricing.lines,
      dropped_items: p.dropped_items,
      warnings,
    },
  },
}];

// Runs when the AI, Google Drive, Google Docs, or Gmail step fails.
// The failed step is the last of these that ran, because the chain stops at the failure.
const req = $('Check Request').first().json;
const steps = [
  ['Create Gmail Draft', 'creating the Gmail draft'],
  ['Fill Proposal Placeholders', 'filling in the proposal doc'],
  ['Copy Proposal Template', 'copying the proposal template'],
  ['Write Proposal', 'writing the proposal with AI'],
];
const failed = steps.find(([name]) => $(name).isExecuted) ?? steps[steps.length - 1];
const err = $input.first().json.error;
const reason = String((err && typeof err === 'object' ? err.message : err) || $input.first().json.message || 'Unknown error');
const escapeHtml = (text) => String(text)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// If the copy was made before the failure, point to it so nothing is lost.
let docUrl = null;
if ($('Copy Proposal Template').isExecuted) {
  const copy = $('Copy Proposal Template').first().json;
  if (copy.id && !copy.error) docUrl = `https://docs.google.com/document/d/${copy.id}/edit`;
}

return [{
  json: {
    ok: false,
    source: req.source,
    statusCode: 502,
    title: "The proposal wasn't finished",
    message: `<p>Something went wrong while ${failed[1]}:</p><p><code>${escapeHtml(reason)}</code></p>`
      + (docUrl ? `<p>The doc was created: <a href="${docUrl}" target="_blank" rel="noopener">open it in Google Docs</a>.</p>` : '')
      + '<p>Check the workflow execution in n8n for details.</p>',
    body: { ok: false, failed_step: failed[0], error: reason, doc_url: docUrl },
  },
}];
